contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit `amount`, call withdrawAll once, then call withdrawAll a second time
    // to observe any further transfers. Assert a single general property combining
    // the observable outcomes for all inputs.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record balances before first withdraw
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform first withdrawAll and record whether it reverted by observing balances
        // We must call withdrawAll as a top-level statement. Use try/catch to avoid reverting the test.
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint afterFirstThis = address(this).balance;
        uint afterFirstC = address(c).balance;

        // perform second withdrawAll as a top-level statement to observe if any further funds are sent
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint afterSecondThis = address(this).balance;
        uint afterSecondC = address(c).balance;

        // Single assert capturing the general rule:
        // If the first withdraw did not revert then:
        //   - this contract's balance increase from beforeFirst to afterFirst is <= amount
        //   - C's balance did not increase (afterFirstC <= beforeC)
        //   - the second withdraw did not increase this contract's balance (afterSecondThis == afterFirstThis)
        // Otherwise (first reverted): we assert that C's balance did not increase by more than the deposit (safety of deposit)
        assert((!firstReverted && afterFirstThis - beforeThis <= amount && afterFirstC <= beforeC && afterSecondThis == afterFirstThis)
               || (firstReverted && afterFirstC - beforeC <= amount));
    }

    receive() external payable {}
}

